/// <summary>
/// AVA/WEN 2024/09/06    AVA_012455_TaxMarkupLedgerAccounts
/// </summary>
/// <param name = "sender">FormDataSource</param>
/// <param name = "e">FormDataSourceEventArgs</param>
[   SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    FormDataSourceEventHandler(formDataSourceStr(MarkupTable, MarkupTable), FormDataSourceEventType::Activated)]
public static void MarkupTable_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
{
    FormFunctionButtonControl   MarkupTaxBtn;
    MarkupTable markupTable = sender.cursor();

    MarkupTaxBtn = sender.formRun().design().controlName(formControlStr(MarkupTable, AVATaxMarkup)) as FormFunctionButtonControl;
    MarkupTaxBtn.enabled((markupTable.ModuleType == MarkupModuleType::Cust && markupTable.VendType == MarkupType::LedgerAccount) || (markupTable.ModuleType == MarkupModuleType::Vend && markupTable.CustType == MarkupType::LedgerAccount));
}

/// <summary>
/// AVA/WEN 2024/09/06    AVA_012455_TaxMarkupLedgerAccounts
/// </summary>
/// <param name = "sender">FormDataObject</param>
/// <param name = "e">FormDataFieldEventArgs</param>
[   SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    FormDataFieldEventHandler(formDataFieldStr(MarkupTable, MarkupTable, CustType), FormDataFieldEventType::Modified)]
public static void CustType_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
{
    FormFunctionButtonControl   MarkupTaxBtn;
    MarkupTable markupTable = sender.datasource().cursor();

    MarkupTaxBtn = sender.datasource().formRun().design().controlName(formControlStr(MarkupTable, AVATaxMarkup)) as FormFunctionButtonControl;
    MarkupTaxBtn.enabled(markupTable.ModuleType == MarkupModuleType::Vend && markupTable.CustType == MarkupType::LedgerAccount);
}

