    FormDataFieldEventHandler(formDataFieldStr(MarkupTable, MarkupTable, VendType), FormDataFieldEventType::Modified)]
public static void VendType_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
{
    FormFunctionButtonControl   MarkupTaxBtn;
    MarkupTable markupTable = sender.datasource().cursor();

    MarkupTaxBtn = sender.datasource().formRun().design().controlName(formControlStr(MarkupTable, AVATaxMarkup)) as FormFunctionButtonControl;
    MarkupTaxBtn.enabled(markupTable.ModuleType == MarkupModuleType::Cust && markupTable.CustType == MarkupType::LedgerAccount);

}
